import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'C'
    if len(history) == 1:
        if history[0][1] == 'D':
            return 'D'
        return 'C'
    if n >= 2:
        last_two_opp = [history[-1][1], history[-2][1]]
        if last_two_opp[0] == 'D' and last_two_opp[1] == 'D':
            return 'D'
        if history[-1][1] == 'D' and rng.random() < 0.9:
            return 'D'
        if history[-1][1] == 'C' and history[-1][0] == 'D' and rng.random() < 0.5:
            return 'C'
        if n >= 5:
            recent = [history[i][1] for i in range(n-5, n)]
            if sum(1 for a in recent if a == 'D') >= 3:
                return 'D'
        if n >= 10:
            all_opp = [h[1] for h in history]
            dc = sum(1 for i in range(1,len(history)) if history[i][1]=='D' and history[i-1][1]=='C')
            cd = sum(1 for i in range(1,len(history)) if history[i][1]=='C' and history[i-1][1]=='D')
            if cd > dc + 2 and all_opp.count('D') > 3:
                return 'D'
        return 'C'
